// Auto-generated from WorldPop 2020 UN-adjusted 1km China open dataset (chn_ppp_2020_1km_Aggregated_UNadj.tif)
// Grid: 212x312 covering Shanghai, Jiangsu, and Zhejiang in Web Mercator game coordinates
export const WORLDPOP_CELL_COLS = 212;
export const WORLDPOP_CELL_ROWS = 312;
export const WORLDPOP_HI_WIDTH = 636;
export const WORLDPOP_HI_HEIGHT = 936;
export const WORLDPOP_CELL_Q_B64 = "";

let cachedCellQ: Uint8Array | null = null;
export function getWorldPopCellQ(): Uint8Array {
  if (cachedCellQ) return cachedCellQ;
  const bin = atob(WORLDPOP_CELL_Q_B64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  cachedCellQ = out;
  return out;
}

export function decodeWorldPopQToDensityKm2(q: number): number {
  const t = Math.max(0, Math.min(1, q / 255));
  return 60000 * Math.pow(t, 1 / 0.48);
}
